seen, applied = set(), []
def ingest(market, order_id, status):
    key = (market, order_id, status)
    if key in seen:
        return "skip"
    seen.add(key); applied.append(key)
    return "apply"

for ev in [("zozo","Z1001","ORDERED"), ("zozo","Z1001","ORDERED"),
           ("tmall","T77","ORDERED"), ("zozo","Z1001","CANCELLED")]:
    print(ev, ingest(*ev))
# ('zozo', 'Z1001', 'ORDERED') apply
# ('zozo', 'Z1001', 'ORDERED') skip
# ('tmall', 'T77', 'ORDERED') apply
# ('zozo', 'Z1001', 'CANCELLED') apply

