ours   = {"SKU-A": 5, "SKU-B": 0, "SKU-C": 12}
market = {"SKU-A": 5, "SKU-B": 3, "SKU-D": 1}
for sku in sorted(ours.keys() | market.keys()):
    if ours.get(sku) != market.get(sku):
        print(sku, "ours", ours.get(sku), "market", market.get(sku))
# SKU-B ours 0 market 3     ← 품절인데 마켓은 3개 판매 중
# SKU-C ours 12 market None ← 마켓에 안 올라감
# SKU-D ours None market 1  ← 우리에게 없는 상품이 마켓에
